    @NonNull
    public static Action futureAction(@NonNull Future<?> future) {
        return new FutureAction(future);
    }

    record JustValue<T, U>(U value) implements Callable<U>, Supplier<U>, Function<T, U> {

        @Override
            public U call() {
                return value;
            }

            @Override
            public U apply(T t) {
                return value;
            }

            @Override
            public U get() {
                return value;
            }
        }

    /**
